        new Instruction { Id = 65, Text = @"Turn on the ice cream maker and pour the mixture into the frozen freezer bowl and let it mix until thickened, about 15 to 20 minutes. When the frozen yogurt is almost done churning, add the chopped pretzels through the opening at the top of the ice cream maker. The frozen yogurt will have a soft, creamy texture. If a firmer consistency is desired, transfer the frozen yogurt to an airtight container and place in freezer for about 2 hours. Remove from freezer about 15 minutes before serving.", Order = 2, RecipeId = 18 },
        new Instruction { Id = 66, Text = @"Mix all ingredients together very well until there are no clumps. (A blender or hand blender is a great tool for this. Simply put all ingredients ito the blender jar and blend on low. If using a hand blender, combine all ingredients into a large mixing bowl and blend until smooth.) Cover and refrigerate a minimum of 2 hours, preferably overnight. Whisk mixture together again before pouring into the ice cream maker.", Order = 1, RecipeId = 15 },
        new Instruction { Id = 67, Text = @"Turn on the ice cream maker and pour the mixture into the frozen freezer bowl and let mix until thickened, about 20 to 25 minutes. The ice cream will have a soft, creamy texture. If a firmer consistency is desired, transfer to an airtight container and place in freezer for about 2 hours. Remove from freezer about 15 minutes before serving.", Order = 2, RecipeId = 15 },
        new Instruction { Id = 68, Text = @"Put the water, honey, and vanilla beans into a small saucepan. Over medium-low heat, bring mixture to a boil, then simmer until reduced by about half. Strain (discarding the vanilla pods); reserve.", Order = 1, RecipeId = 16 },
        new Instruction { Id = 69, Text = @"In a large bowl, whisk the yogurt, reserved honey/water/vanilla reduction, vanilla extract, sugar, and salt together. Whisk until the sugar has dissolved. Cover and refrigerate a minimum of 2 hours, preferably overnight. Whisk mixture together again before pouring into the ice cream maker.", Order = 2, RecipeId = 16 },
        new Instruction { Id = 70, Text = @"Turn on the ice cream maker and pour the mixture into the frozen freezer bowl and let mix until thickened, about 8 to 10 minutes. The frozen yogurt will have a soft, creamy texture. If a firmer consistency is desired, transfer the frozen yogurt to an airtight container and place in freezer for about 2 hours. Remove from freezer about 15 minutes before serving.", Order = 3, RecipeId = 16 },
        new Instruction { Id = 71, Text = @"In a large mixing bowl, whisk together yogurt, salt, ad sugar together; reserve.", Order = 1, RecipeId = 17 },
