        new Instruction { Id = 73, Text = @"Turn on the ice cream maker and pour the mixture into the frozen freezer bowl and let mix until thickened, about 15 to 20 minutes. The frozen yogurt will have a soft, creamy texture. If a firmer consistency is desired, transfer to frozen yogurt to an airtight container and place in freezer for about 2 hours. Remove from freezer about 15 minutes before serving.", Order = 3, RecipeId = 17 },
        new Instruction { Id = 74, Text = @"In a large mixing bowl, whisk together yogurt, salt, and sugar together; reserve.", Order = 1, RecipeId = 17 },
        new Instruction { Id = 75, Text = @"In a medium bowl, use a hand mixer on low speed or whisk to combine all of the ingredients. Cover and refrigerate a minimum of 2 hours, preferably overnight. Whisk mixture together again before pouring into ice cream machine.", Order = 1, RecipeId = 14 },
        new Instruction { Id = 76, Text = @"Turn on the ice cream maker and pour the mixture into the frozen freezer bowl and let mix until thickened, about 20 to 25 minutes. The ice cream will have a soft texture. If a firmer consistency is desired, transfer to an airtight container and place in freezer for about 2 hours. Remove from freezer about 15 minutes before serving.", Order = 2, RecipeId = 14 },
        new Instruction { Id = 77, Text = @"Prepare a simple syrup with the water, sugar, and salt by combining all three in a medium saucepan set of medium-low heat. Cook mixture until the sugar is fully dissolved. Remove from heat.", Order = 1, RecipeId = 12 },
