        new Instruction { Id = 78, Text = @"Gradually add the cocoa powder to the simple syrup by whisking constantly until smooth. Add the vanilla extract and stir to combine. Cool to room temperature. Cover and refrigerate a minimum of 2 hours, preferably overnight. Whisk mixture together again before pouring into the ice cream machine.", Order = 2, RecipeId = 12 },
        new Instruction { Id = 79, Text = @"Turn on the ice cream maker and pour the mixture into the frozen freezer bowl and let mix until thickened, about 20 to 25 minutes. The sorbet will have a soft, creamy texture. If a firmer consistency is desired, transfer the sorbet to an airtight container and place in the freezer for about 2 hours. Remove from freezer about 15 minutes before serving.", Order = 3, RecipeId = 12 },
