        new Instruction { Id = 83, Text = @"Turn on the ice cream maker and pour the mixture into the frozen freezer bowl and let mix until thickened, about 25 to 30 minutes. The sorbet will have a soft, creamy texture. If a firmer consistency is desired, transfer the sorbet to an airtight container and place in the freezer for about 2 hours. Remove from freezer about 15 minutes before serving.", Order = 4, RecipeId = 13 },
        new Instruction { Id = 84, Text = @"In a medium saucepan set over medium/medium-low heat, whisk together the milk, cream, half of the sugar, salt, and vanilla extract. Bring the mixture just to a boil.", Order = 1, RecipeId = 11 },
        new Instruction { Id = 85, Text = @"While the milk/cream mixture is heating, combine the yolks and remaining sugar in a medium bowl. Using a hand mixer on low speed or whisk, beat until mixture is pale and thickened.", Order = 2, RecipeId = 11 },
        new Instruction { Id = 86, Text = @"Once the milk/cream mixture has come to a slight boil, whisk about 1/3 of the hot mixture into the yolk/sugar mixture. Add another 1/3 of the mixture, then return the combined mixture to the saucepan. Using a wooden spoon, stir in the mixture constantly over low heat until it thickens slightly and coats the back of a spoon. The mixture must NOT boil or the yolks will overcook - the process should take 10 minutes, depending on the type of pan and stove being used.", Order = 3, RecipeId = 11 },
        new Instruction { Id = 87, Text = @"Pour the mixture through a fine mesh strainer and bring to room temperature. Cover and refrigerate a minimum of 2 hours, preferably overnight. Whisk mixture together again before pouring into the ice cream maker.", Order = 4, RecipeId = 11 },
        new Instruction { Id = 88, Text = @"Once the ice cream base has become sufficiently cooled, prepare the caramel sauce. Put the sugar, salt, and water in a heavy-bottomoed, small saucepan set over medium heat. Keep an eye on the caramel and allow to cook until amber in color (the color of maple syrup). Remove from heat and stir in the heavy cream and butter (it will froth a bit, so ad them slowly). Whisk together and thens et aside utnil ready to use. Allow to cool to room temperature.", Order = 5, RecipeId = 11 },
        new Instruction { Id = 89, Text = @"Reserve 2 tablespoons of the caramel sauce and add the rest to the cream base. Whisk well to combine.", Order = 6, RecipeId = 11 },
        new Instruction { Id = 90, Text = @"Turn on the ice cream maker and pour the mixture into the frozen freezer bowl and let mix until thickened, about 15 minutes. The ice cream will have a soft, creamy texture. Right before turning the ice cream maker off, slowly drizzle in the reserved 2 tablespoons of caramel sauce. Allow to mix for no more than a few revolutions to make a nice swirl.", Order = 7, RecipeId = 13 },
        new Instruction { Id = 91, Text = @"If a firmer consistency is desired, transfer the ice cream to an airtight container and place in freezer for about 2 hours. Remove from freezer about 15 minutes before serving.", Order = 8, RecipeId = 11 },
        new Instruction { Id = 92, Text = @"Garnish each serving with a pinch of the flaked sea salt.", Order = 9, RecipeId = 11 },
        new Instruction { Id = 93, Text = @"In a medium saucepan set over medium/medium-low heat, whisk together the milk, cream, vanilla extract, spices, and the salt and 1/2 of the sugar. Bring the mixture just to a boil.", Order = 1, RecipeId = 10 },
        new Instruction { Id = 94, Text = @"While the milk/cream mixture is heating, combine the yolks and remaining sugar in a medium bowl. Using a hand mixer on low speed or whisk, beat until mixture is pale and thick.", Order = 2, RecipeId = 10 },
        new Instruction { Id = 95, Text = @"Place the chopped chocolate in a separate mixing bowl; reserve.", Order = 3, RecipeId = 10 },
        new Instruction { Id = 96, Text = @"Once the milk/cream mixture has come to a slight boil, whisk about 1/3 of the hot mixture into the yolk/sugar mixture. Add another 1/3 of the mixture, then return the combined mixture to the saucepan. Using a wooden spoon, stir the mixture constantly over low heat until it thickens slightly and coats the back of the spoon. This mixture must NOT boil or the yolks will overcook - the process should take about 10 minutes, depnding on the type of pan and stove being used.", Order = 4, RecipeId = 10 },
        new Instruction { Id = 97, Text = @"Pour the mixture through a fie mesh strainer into the bowl of the reserved chocolate; whisk until chocolate is fully melted and mixture is well combined and then bring to room temperature. Cover and refrigerate a minimum of 2 hours, preferably overnight. Whisk mixture together again before pouring into the ice cream maker.", Order = 5, RecipeId = 10 },
        new Instruction { Id = 98, Text = @"Turn on the ice cream maker and pour the mixture into the frozen freezer bowl and let mix until thickened, about 20 minutes. The ice cream will have a soft, creamy texture. If a firmer consistency is desired, transfer the ice cream to an airtight container and place in freezer for about 2 hours. Remvoe from freezer about 15 minutes before serving.", Order = 6, RecipeId = 10 },
        new Instruction { Id = 99, Text = @"In a medium bowl, whisk together the cocoa, sugars, and salt. Add the milk and, using a hand mixer on low speed or whisk, beak to combine until the cocoa and sugars are dissolved. Stir in the heavy cream and vanilla extract. Cover and refrigerate a minimum of 2 hours, preferably overnight. Whisk mixture together again before consuming.", Order = 1, RecipeId = 6 },
        new Instruction { Id = 100, Text = @"Turn on the ice cream machine and pour the mixture into the frozen freezer bowl and let mix until thickened, about 12 to 15 minutes. A few minutes before mixing is completed, gradually add the marshmallows, crushed graham crackers and melted chocolate. Let mix in completely, an aditional minute or two. The ice cream will have a soft, creamy texture. If a firmer consistency is desired, transfer the ice cream to an airtight container and place in freezer for about 2 hours. Remove from freezer about 15 minutes before serving.", Order = 2, RecipeId = 6 },
        new Instruction { Id = 101, Text = @"In a medium bowl, use a hand mixer on low speed or whisk to combine to cream, milk, vanilla extract, and salt. Reserve.", Order = 1, RecipeId = 7 },
        new Instruction { Id = 102, Text = @"In a large frypan set over medium heat, cook the sugar with water until it begins to sizzle. Stir in the butter adn cook until melted. Add the bananas; cook for 2 minutes or until fragrant and softened. Carefully stir in the rum and cook at a strong simmer for an additional 2 minutes or until slightly thickened. Remove from heat. Using a slotted spoon, strain the banana/sugar mixture, reserving the sugar syrup and bananas in separate bowls.", Order = 2, RecipeId = 7 },
        new Instruction { Id = 103, Text = @"Stir the lemon juice into the bananas and then mix the bananas into the steeped milk/cream. Cover and refrigerate a minimum of 2 hours, preferably overnight. Whisk mixture together again before pouring into the ice crema machine. If you aer not freezing the ice cream same day, cool the sugar syrup to room temperature. Warm prior to freezing ice cream to liquefy the syrup.", Order = 3, RecipeId = 7 },
        new Instruction { Id = 106, Text = @"When the ice cream is almost fully hurned, gradually add the sugar syrup; let mix until fully combined. Once the sugar syrup has been mixed, add the walnuts through the top of the ice cream container. Let mix until combined. Right before the ice cream is done, drizzle the melted chocolate into the churning ice cream. The ice cream will have a soft, creamy texture. If a firmer consistency is desired, transfer the ice cream to an airtight container and place in freezer for about 2 hours. Remove from freezer for about 2 hours. Remove from freezer about 15 minutes before serving.", Order = 6, RecipeId = 7 },
        new Instruction { Id = 107, Text = @"In a medium saucepan set over medium/medium-low heat, whisk together the  milk, cream, half of the sugar, salt, and the scraped vanilla bean (including the pod). Bring the mixture just to a boil.", Order = 1, RecipeId = 8 },
        new Instruction { Id = 108, Text = @"While the milk/cream mixture is heating, combine the yolks and remaining sugar in a medium bowl. Using a hand mixer on low speed or whisk, beat until mixture is pale and thick.", Order = 2, RecipeId = 8 },
        new Instruction { Id = 109, Text = @"Once the milk/cream mixture has come to a slight boil, whisk about 1/3 of the hot mixture ito the yolk/sugar mixture. Add another 1/3 of the  mixture, then return the combined mixture to the saucepan. Using a wooden spoon, stir in the mixure constantly over low heat until it thickens slightly and coats the back of the spoon. This mixture must NOT boil or the yolks will overcook - the process should take about 10 minutes, depending on the type of pan and stove being used.", Order = 3, RecipeId = 8 },
        new Instruction { Id = 110, Text = @"Pour the mixture through a fine mesh strainer (discard the vanilla pod) and bring the room temperature. Stir in the vanilla extract. Cover and refrigerate a minimum of 2 hours, preferably overnight. Whisk mixture together again before pouring into the ice cream maker.", Order = 4, RecipeId = 8 },
        new Instruction { Id = 111, Text = @"Turn on the ice cream maker and pour the mixture into the frozen freezer bowl and let mix until thickened, about 20 minutes. The ice cream will have a soft, creamy texture. If a firmer consistency is desired, transfer the ice cream to an airtight container and place in freezer for about 2 hours. Remove from freezer about 15 minutes before serving.", Order = 5, RecipeId = 8 },
        new Instruction { Id = 112, Text = @"In a medium saucepan set over medium/medium-low heat, whisk together the milk, cream, half of the granulated sugar, salt, and vanilla extract. Bring the mixture just to a boil. Remove from heat and add the mint leaves; let steep for 20 to 30 minutes. If you desire a milder mint flavor, remove and discard the mint leaves after steeping, but for a mroe intense ice cream we recommend blending the milk/mint mixture using an immersion blender. After steeping, return the mixture just to a boil over medium-low heat.", Order = 1, RecipeId = 9 },
        new Instruction { Id = 113, Text = @"While the milk/cream mixture is reheating, combine the yolks and remaining sugar in a medium bowl. Using a hand mixer on low speed or a whisk, beat until mixture is pale and thick.", Order = 2, RecipeId = 9 },
        new Instruction { Id = 114, Text = @"Once the milk/cream mixture has come to a slight boil, whisk about 1/3 of the hot mixture into the yolk/sugar mixture. Add another 1/3 of the mixture, then return the combined mixture to the saucepan. Using a wooden spoon, stir the mixture constantly over low heat until it thickens slightly and coats the back of the spoon. This mixture must NOT boil or the yolks will overcook - the process should take about 10 minutes, depending on the type of pan and stove being used.", Order = 3, RecipeId = 9 },
        new Instruction { Id = 115, Text = @"Pour the mixture through a fine mesh strainer. Bring the ice cream base to room temperature. Cover and refrigerate a minimum of 2 hours, preferably overnight. Whisk mixture together again before pouring into the ice cream maker.", Order = 4, RecipeId = 9 },
        new Instruction { Id = 116, Text = @"Turn on the ice cream maker and pour the mixture into the frozen freezer bowl and let mix until thickened, about 20 minutes. When the ice cream is almost churned, gradually add the crushed cookies through the top of the ice cream maker. Let mix until fully combined.", Order = 5, RecipeId = 9 },
        new Instruction { Id = 117, Text = @"The ice cream will have a soft, creamy texture. If a firmer consistency is desired, transfer the ice cream to an airtight container and place in freezer for about 2 hours. Remove from freezer about 15 minutes before serving.", Order = 6, RecipeId = 9 },
